        # simpler: iterate positions from top
        for r in range(H-o['h']):
            ok=all(O[r+a][b]==0 for a,b in zip(rels,offs) for rels,offs in [([],[])]) 
        # redo cleanly below
        break
    placed_objs=[]
    # top objects: try each at row 0; if collision with placed, skip? assume none conflict
    for o in sorted(top,key=lambda o:o['orig_minrow']):
        offr=[r-r0 for r,_ in o['cells']]; offc=[c-c0 for _,c in o['cells']]
        ok=all(O[a][b]==0 for a,b in zip(offr,offc))
        if ok:
            for a,b in zip(offr,offc): O[a][b]=o['col']; placed_objs.append((o,a,offr,offc))
        else:
            # slide down until clear
            r=0
            while r<=H-o['h'] and not all(O[r+a][b]==0 for a,b in zip(offr,offc)): r+=1
            for a,b in zip(offr,offc): O[r+a][b]=o['col']; placed_objs.append((o,r,offr,offc))
    for o in sorted(bot,key=lambda o:-o['orig_minrow']):  # bottom-most first
