from collections import Counter
def f(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; st.append((x,y))
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                # is it a full rectangular ring? bbox fully colored on boundary with interior 0
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                ring=all(g[a][b]==col for a in (r0,r1) for b in range(c0,c1+1)) and all(g[a][b]==col for b in (c0,c1) for a in range(r0,r1+1))
                comps.append({'col':col,'ring':ring,'cells':set(cells),'bbox':(r0,c0,r1,c1)})
    cnt=Counter(c['col'] for c in comps)
    out=[[0]*W for _ in range(H)]
    for c in sorted(comps,key=lambda c:c['bbox'][0]):
        if c['ring'] and cnt[c['col']]==1:
            r0,r1,cc,_=c['bbox']; dr=r0  # move to top
            for a,b in c['cells']:
                out[a-dr][b]=c['col']
        else:
            for a,b in c['cells']: out[a][b]=c['col']
    return out
