# Test input objects (all open rings): 3-ring rows2-4 c3-5, 8-ring rows3-5 c0-2, 2-ring rows1-3 c10-14, 
# 1-rings: rows6-9 c4-7; rows6-9 c10-14; rows8-11 c11-14 (rows 8-11: '1' at r8c11? check: r8 c11..14 = 1s -> ring rows8-11 c11-14). 2-ring rows10-12 c0-2.
# Which move to top? In demo3: ALL open rings moved to top, stacking by column order from left: 2(c2),3(c9),8(c12).
# So all open rings shift up to row0 in their own column band, keeping columns? Demo3 col kept yes (col2->col2). Stacking not needed since they're in separate columns.
def f(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=set()
                while st:
                    a,b=st.pop(); cells.add((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; st.append((x,y))
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                ring=all(g[a][b]==col or g[a][b]==0 for a in range(r0,r1+1) for b in range(c0,c1+1)) \
                      and len(cells)==2*(r1-r0+1+c1-c0+1)-4 and (r1-r0==c1-c0) and (len(cells)==2*(r1-r0+1)+2*(c1-c0+1)-4)
                # simpler: hollow rectangle exactly (check ring property: boundary all col, interior all 0)
                okring=all(g[a][b]==col for a in (r0,r1) for b in range(c0,c1+1)) and all(g[a][b]==col for b in (c0,c1) for a in range(r0,r1+1))
                comps.append({'col':col,'cells':cells,'r0':r0,'c0':c0,'h':r1-r0+1,'w':c1-c0+1,'ring':oking})
    out=[row[:] for row in [0]*H]
    for comp in sorted(comps,key=lambda c:(c['r0'],c['c0'])):
        if comp['ring']:
            h=comp['h']; w=comp['w']
            for a in range(h):
                for b in range(w):
                    rr=max(a+comp['r0']-0,0); cc=b+comp['c0']
                    out[max(rr-comp['r0'],0)][cc]=comp['col']
        else:
            for a,b in comp['cells']:
                out[a][b]=comp['col']
    return out
