def solid(a):
    H,W=len(a),len(a[0]); cells={(i,j) for i in range(H) for j in range(W) if a[i][j]!=0}
    comps=[]; seen=set()
    for (i,j) in sorted(cells):
        if (i,j) in seen: continue
        st=[(i,j)]; comp=[]
        while st:
            p=st.pop(); comp.append(p)
            c=a[p[0]][p[1]]
            for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                n=(p[0]+di,p[1]+dj)
                if n in cells and a[n[0]][n[1]]==c and n not in seen:
                    seen.add(n); st.append(n)
        comps.append((c,comp))
    o=[[0]*W for _ in range(H)]
    for c,comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        for i in range(min(rs),max(rs)+1):
            for j in range(min(cs),max(cs)+1): o[i][j]=c
    return o
