def comps_of(grid,bg):
    H,W=len(grid),len(grid[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if grid[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    r,c=st.pop(); cells.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            n=(r+dr,c+dc)
                            if 0<=n[0]<H and 0<=n[1]<W and grid[n]==grid[r][c] and n not in seen:
                                seen.add(n); st.append(n)
                res.append((grid[i][j],set(cells)))
    return res

def test_rule(name,f):
    ok=True; bad=[]
    for n in range(1,9):
        a=np.array(G[f'Demo pair {n} input']); b=np.array(G[f'Demo pair {n} output'])
        bg=Counter(a.flatten()).most_common(1)[0][0]
        try:
            pred=f(a,bg)
            # allow cropping: compare subgrids if shapes differ; take largest common window
            if pred.shape!=b.shape:
                h=min(pred.shape[0],b.shape[0]); w=min(pred.shape[1],b.shape[1])
                if not (pred[:h,:w]==b[:h,:w]).all(): ok=False; bad.append((n,'shape/mismatch'))
                else: ok=False; bad.append((n,'crop_mismatch'))
                continue
            if (pred==b).all(): continue
            ok=False; bad.append((n,'mismatch',np.argwhere(pred!=b)[:5].tolist()))
        except Exception as e:
            ok=False; bad.append((n,str(e)))
    print(name, ok, bad)
    return ok,bad

# Rule R1: bbox-interior (strictly inside bbox) -> 8
def R1(a,bg):
    g=a.copy(); H,W=g.shape
    for c,cells in comps_of(g,bg):
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        for r,c in cells:
            if r0<r<r1 and c0<c<c1: g[r,c]=8
    return g
test_rule('R1 bbox-interior',R1)

# Rule R2: 8-neighborhood interior -> 8
def R2(a,bg):
    g=a.copy(); H,W=g.shape
    for c,cells in comps_of(g,bg):
        S=set(cells)
        for r,c in cells:
            nb={(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)} & S
            if len(nb)==8: g[r,c]=8
    return g
test_rule('R2 8-interior',R2)

# Rule R3: 4-neighborhood interior (original attempt)
def R3(a,bg):
    g=a.copy(); H,W=g.shape
    for c,cells in comps_of(g,bg):
        S=set(cells)
        for r,c in cells:
            nb={(r+dr,c+dc) for dr,dc in((1,0),(-1,0),(0,1),(0,-1))} & S
            if len(nb)==4: g[r,c]=8
    return g
test_rule('R3 4-interior',R3)

