import numpy as np
from collections import Counter
def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    r,c=st.pop(); cells.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            n=(r+dr,c+dc)
                            if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==g[r][c] and n not in seen:
                                seen.add(n); st.append(n)
                res.append((g[i][j],set(cells)))
    return res

def slide(g):
    g=[row[:] for row in g]; H=len(g); W=len(g[0])
    bg=Counter(sum(g,[])).most_common(1)[0][0]
    objs=comps(g,bg)
    objsets=[o for c,o in objs if len(o)>=2]
    occupied=lambda S: False
    changed=True
    while changed:
        changed=False
        for o in objsets:
            my=sum(p[0] for p in o)/len(o); myc=sum(p[1] for p in o)/len(o)
            best=None
            for t in objsets:
                if t is o: continue
                tc=sum(p[0] for p in t)/len(t); tcc=sum(p[1] for p in t)/len(t)
                d=min(abs(a[0]-b[0])+abs(a[1]-b[1]) for a in o for b in t)
                if best is None or d<best[0]: best=(d,tc,tcc,t)
            if best is None: continue
            _,_,_,t=best
            dr=int(np.sign(tc-my)); dc=int(np.sign(tcc-myc))
            if dr==0 and dc==0: continue
            collides=False
            for (r,c) in o:
                nr,nc=r+dr,c+dc
                if not(0<=nr<H and 0<=nc<W) or any((nr,nc) in t for t in [] if False) or ((nr,nc) in t): collides=True
            if collides: continue
            for (r,c) in list(o): g[r][c]=bg
            o={(r+dr,c+dc) for r,c in o}
            changed=True
        if not changed: break
    gnew=[[bg]*W for _ in range(H)]
    for c,o in comps(g,bg):
        if len(o)>=2:
            for (r,cc_) in o: gnew[r][cc_]=c
        else:
            # singleton attaches to nearest multi-object
            best=None
            for c2,o2 in comps(g,bg):
                if len(o2)<2: continue
                dd=min(abs(r-a)+abs(cc_-b) for a,b in o2)
                if best is None or dd<best[0]: best=(dd,c2)
            if best: gnew[r][cc_]=best[1]
    return gnew

